import hre from "hardhat";
const { ethers } = hre;

async function main() {
    await hre.network.provider.request({
        method: "hardhat_reset",
        params: [{
            forking: {
                jsonRpcUrl: "https://eth-sepolia.g.alchemy.com/v2/BBqgWCw5DmqAkIKhZfT0h",
            }
        }]
    });

    const data = "";
    const TO = "0xc8596bbbF270C4E54752ddE1D4b4e67F81b9b4F0";
    const FROM = "0x53a3ed1d3512a40350d446c7b625B634014f6FC0";
    
    await hre.network.provider.request({
        method: "hardhat_impersonateAccount",
        params: [FROM],
    });
    await hre.network.provider.send("hardhat_setBalance", [FROM, "0x1000000000000000000"]);

    const signer = await ethers.getSigner(FROM);

    console.log("Simulating with gas...");
    try {
        const tx = await signer.sendTransaction({
            to: TO,
            data: data,
            value: "0x470de4df820000", // 0.02 ETH
            gasLimit: 3000000
        });
        const rx = await tx.wait();
        console.log("Success! Gas:", rx.gasUsed.toString(), "Status:", rx.status);
    } catch(e) {
        console.error("Reverted!");
        console.error(e.message);
        if (e.receipt) {
            console.log("Receipt status:", e.receipt.status);
        }
    }
}
main();
